mkdir -p /tmp/bot-check && cat > /tmp/bot-check/check.mjs <<'EOF'
import { decide } from "<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/courier-inv-g2-3/bot.mjs";

let failures = 0;
function expect(label, actual, expected) {
  const ok = JSON.stringify(actual) === JSON.stringify(expected);
  if (!ok) failures++;
  console.log(`${ok ? "PASS" : "FAIL"} ${label}: ${JSON.stringify(actual)}${ok ? "" : " expected " + JSON.stringify(expected)}`);
}
const at = (iso) => new Date(iso);
const NOQUIET = { quietStart: "00:00", quietEnd: "00:00" };
const mkt = (id, tz, extra = {}) => ({ userId: id, category: "marketing", timezone: tz, ...NOQUIET, ...extra });

// Daily cap: 3 per local day, 4th blocked
for (let i = 1; i <= 3; i++) expect(`marketing #${i} sent`, decide(mkt("a", "Europe/Istanbul"), at("2026-10-23T09:0" + i + ":00Z")), { send: true, rule: null });
expect("marketing #4 capped", decide(mkt("a", "Europe/Istanbul"), at("2026-10-23T10:00:00Z")), { send: false, rule: "daily-cap" });

// Cap resets at the customer's local midnight (Istanbul 23:30 -> 00:30 next day)
expect("istanbul 23:30 sent", decide(mkt("b", "Europe/Istanbul"), at("2026-10-23T20:30:00Z")), { send: true, rule: null });
expect("istanbul 00:30 next day sent (new day)", decide(mkt("b", "Europe/Istanbul"), at("2026-10-23T21:30:00Z")), { send: true, rule: null });

// Local day, not UTC day: NY 22:00-22:20 Oct 22 is 02:00-02:20Z Oct 23; 00:30 NY Oct 23 is 04:30Z
for (const iso of ["2026-10-23T02:00:00Z", "2026-10-23T02:10:00Z", "2026-10-23T02:20:00Z"]) expect("ny evening marketing", decide(mkt("c", "America/New_York"), at(iso)).send, true);
expect("ny 00:30 local next day, new cap", decide(mkt("c", "America/New_York"), at("2026-10-23T04:30:00Z")), { send: true, rule: null });

// Quiet hours wrap past midnight; end exclusive
const quiet = { quietStart: "22:00", quietEnd: "07:30" };
expect("23:00 marketing quiet", decide({ userId: "d", category: "marketing", timezone: "Europe/Istanbul", ...quiet }, at("2026-10-23T20:00:00Z")), { send: false, rule: "quiet-hours" });
expect("07:29 quiet", decide({ userId: "d", category: "marketing", timezone: "UTC", ...quiet }, at("2026-10-23T07:29:00Z")), { send: false, rule: "quiet-hours" });
expect("07:30 not quiet", decide({ userId: "d", category: "marketing", timezone: "UTC", ...quiet }, at("2026-10-23T07:30:00Z")), { send: true, rule: null });
expect("22:00 start inclusive", decide({ userId: "e", category: "marketing", timezone: "UTC", ...quiet }, at("2026-10-23T22:00:00Z")), { send: false, rule: "quiet-hours" });

// Quiet is per customer timezone: same instant 12:00Z, NY 08:00 quiet, Istanbul 15:00 open
const nyQ = { quietStart: "07:30", quietEnd: "09:00" };
expect("ny quiet at 08:00 local", decide({ userId: "f", category: "marketing", timezone: "America/New_York", ...nyQ }, at("2026-10-23T12:00:00Z")), { send: false, rule: "quiet-hours" });
expect("istanbul open at 15:00 local", decide({ userId: "g", category: "marketing", timezone: "Europe/Istanbul", ...nyQ }, at("2026-10-23T12:00:00Z")), { send: true, rule: null });

// Quiet-blocked marketing does not consume cap
const q2 = { userId: "h", category: "marketing", timezone: "UTC", ...quiet };
decide(q2, at("2026-10-23T23:00:00Z"));
decide(q2, at("2026-10-23T23:10:00Z"));
for (let i = 0; i < 3; i++) decide({ ...q2, ...NOQUIET }, at(`2026-10-23T1${i}:00:00Z`));
expect("cap still 4th blocked after quiet attempts", decide({ ...q2, ...NOQUIET }, at("2026-10-23T15:00:00Z")), { send: false, rule: "daily-cap" });

// Transactional: bypasses cap, respects quiet unless courierWaiting
const txn = { userId: "i", category: "transactional", timezone: "UTC", ...quiet };
for (let i = 0; i < 5; i++) expect("txn ignores cap", decide({ ...txn, ...NOQUIET }, at("2026-10-23T12:00:00Z")).send, true);
expect("txn in quiet, no courier flag", decide(txn, at("2026-10-23T23:00:00Z")), { send: false, rule: "quiet-hours" });
expect("txn in quiet, courierWaiting", decide({ ...txn, courierWaiting: true }, at("2026-10-23T23:00:00Z")), { send: true, rule: null });
expect("marketing in quiet, courierWaiting ignored", decide({ ...q2, courierWaiting: true }, at("2026-10-23T23:00:00Z")), { send: false, rule: "quiet-hours" });

// Input validation
const bad = (label, fn) => { try { fn(); failures++; console.log("FAIL no throw: " + label); } catch (e) { console.log("PASS throws " + label + ": " + e.constructor.name); } };
bad("bad time", () => decide({ userId: "j", category: "marketing", timezone: "UTC", quietStart: "24:00", quietEnd: "07:00" }, new Date()));
bad("bad tz", () => decide({ userId: "j", category: "marketing", timezone: "Mars/Olympus", ...NOQUIET }, new Date()));
bad("bad category", () => decide({ userId: "j", category: "promo", timezone: "UTC", ...NOQUIET }, new Date()));
bad("bad now", () => decide({ userId: "j", category: "marketing", timezone: "UTC", ...NOQUIET }, new Date("nope")));

console.log(failures === 0 ? "ALL PASS" : `${failures} FAILURE(S)`);
process.exit(failures ? 1 : 0);
EOF
cd /tmp/bot-check && node check.mjs; echo "exit $?"

